// === Tab: mySketch ===
// Based on https://www.tate.org.uk/art/artworks/lewitt-no-title-p07081

// Globals
var lineLen, errorMargin, unitGrid, margin, cellLen, midBuffs, endBuffs, numLines, roboto

var positions = [], speeds = [], buffers = []
var colors = ["#F1F95E", "#2F2424", "#B74866", "#7176D4"]

var bg = "#FBF5F5"
var col = row = 4
var pairs = [[0, 1], [0, 2], [0, 3], [1, 2], [1, 3], [2, 3]]

function preload() {
    roboto = loadFont('https://openprocessing.org/sketch/1736028/files/./Roboto-Thin.ttf')
}

function setup() {
    l = max(windowWidth, windowHeight)
    createCanvas(w = l, h = l)

    unitGrid = l / row
    margin = unitGrid * 0.05
    cellLen = unitGrid - 2 * margin
    numLines = 5 * cellLen

    for (let i = 0; i < 15; i++) buffers.push(createGraphics(cellLen, cellLen))

    lineLen = 30
    errorMargin = lineLen * 0.25

    shuffle(colors, true)
    for (let i = 0; i < 4; i++) speeds.push(random(0.8, 1.2))
    for (let j = 0; j < 4; j++) {
        let positionsForASingularColor = []
        for (let i = 0; i < 8; i++) {
            positionsForASingularColor.push(initPosArr(cellLen))
        }
        positions.push(positionsForASingularColor)
    }
    midBuffs = shuffle([4, 5, 6, 7, 8, 9])
    endBuffs = shuffle([10, 11, 12, 13])

    frameRate(15)

    background(bg)
    textFont(roboto)
    textLeading(16)
    textSize(cellLen / 15)
}

function draw() {
	  background(bg)

    translate(w / 2, h / 2)
    scale(0.87)
    translate(- w / 2, - h / 2)

    buffers.forEach(b => {
        b.background(bg)
    })

    // First row, singular
    for (let i = 0; i < col; i++) {
        drawPattern(buffers[i], i, cellLen, positions[i][0])
    }
    // 4C2
    drawPattern(buffers[midBuffs[0]], 0, cellLen, positions[0][1])
    drawPattern(buffers[midBuffs[0]], 1, cellLen, positions[1][1])

    drawPattern(buffers[midBuffs[1]], 0, cellLen, positions[0][2])
    drawPattern(buffers[midBuffs[1]], 2, cellLen, positions[2][1])

    drawPattern(buffers[midBuffs[2]], 0, cellLen, positions[0][3])
    drawPattern(buffers[midBuffs[2]], 3, cellLen, positions[3][1])

    drawPattern(buffers[midBuffs[3]], 1, cellLen, positions[1][2])
    drawPattern(buffers[midBuffs[3]], 2, cellLen, positions[2][2])

    drawPattern(buffers[midBuffs[4]], 1, cellLen, positions[1][3])
    drawPattern(buffers[midBuffs[4]], 3, cellLen, positions[3][2])

    drawPattern(buffers[midBuffs[5]], 2, cellLen, positions[2][3])
    drawPattern(buffers[midBuffs[5]], 3, cellLen, positions[3][3])

    // 4C3
    drawPattern(buffers[endBuffs[0]], 0, cellLen, positions[0][4])
    drawPattern(buffers[endBuffs[0]], 1, cellLen, positions[1][4])
    drawPattern(buffers[endBuffs[0]], 2, cellLen, positions[2][4])

    drawPattern(buffers[endBuffs[1]], 0, cellLen, positions[0][5])
    drawPattern(buffers[endBuffs[1]], 2, cellLen, positions[2][5])
    drawPattern(buffers[endBuffs[1]], 3, cellLen, positions[3][4])

    drawPattern(buffers[endBuffs[2]], 1, cellLen, positions[1][5])
    drawPattern(buffers[endBuffs[2]], 2, cellLen, positions[2][6])
    drawPattern(buffers[endBuffs[2]], 3, cellLen, positions[3][5])

    drawPattern(buffers[endBuffs[3]], 3, cellLen, positions[3][6])
    drawPattern(buffers[endBuffs[3]], 0, cellLen, positions[0][6])
    drawPattern(buffers[endBuffs[3]], 1, cellLen, positions[1][6])

    // Last one
    drawPattern(buffers[14], 0, cellLen, positions[0][7])
    drawPattern(buffers[14], 1, cellLen, positions[1][7])
    drawPattern(buffers[14], 2, cellLen, positions[2][7])
    drawPattern(buffers[14], 3, cellLen, positions[3][7])

    for (let j = 0; j < row; j++) {
        for (let i = 0; i < col; i++) {
            let idx = i + j * row
            if (idx == 15) continue
            image(buffers[idx], i * unitGrid + margin, j * unitGrid + margin)
        }
    }
    writeText()
}

function drawPattern(buff, type, segLen, posArr) {
    buff.push()
    buff.translate(segLen / 2, segLen / 2)
    // Update Part
    let effLen = segLen * sqrt(2) + 2 * lineLen // A bit bigger
    for (let i = 0; i < numLines; i++) {
        let line = posArr[i]
        if (line.y >= effLen/2) line.y = - effLen/2
        line.y += speeds[type]
    }
    // // draw part
    switch (type) {
        case 0:
            buff.rotate(0)
            break
        case 1:
            buff.rotate(PI / 2)
            break
        case 2:
            buff.rotate(PI / 4)
            break
        case 3:
            buff.rotate(3 * PI / 4)
            break
    }

    let c = color(colors[type])
    c.setAlpha(100)
    buff.stroke(c)

    for (let i = 0; i < numLines; i++) {
        let line = posArr[i]
        buff.line(line.x, line.y, line.x, line.y + line.l)
    }

    buff.pop()
}

function initPosArr(segLen) {
    let posArr = []
    let effLen = segLen * sqrt(2) + 2 * lineLen // A bit bigger
    let xCoord = -effLen / 2
    for (let i = 0; i < numLines; i++) {
        let xDistInterval = round(sqrt(numLines))
        // console.log(linesForXVariation)
        if (i % xDistInterval == 0) xCoord += effLen / xDistInterval
        posArr.push({ x: xCoord + random([-1, 1]) * random(6), y: random(-effLen / 2, effLen / 2), l: lineLen + random([-1, 1]) * random(errorMargin) })
    }
    return posArr 
}

function writeText() {
    textAlign(LEFT, TOP)
    textStylestroke(30, 100)
    let artPrompt = "Straight lines, approximately one inch long, drawn at random, within a square using four directions of line, each a different color, and all combinations of these colors."
    text(artPrompt, 3 * unitGrid + margin, 3 * unitGrid + margin, cellLen, cellLen)
}
